import express from 'express';
import cors from 'cors';
import { PGLite } from '@electric-sql/pglite';
import fs from 'fs/promises';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, 'data');

const app = express();
app.use(cors());
app.use(express.json());

let db;

async function initDb() {
  // Ensure data directory exists
  try {
    await fs.access(DATA_DIR);
  } catch {
    await fs.mkdir(DATA_DIR, { recursive: true });
  }

  // Initialize PGLite with file system persistence
  db = new PGLite(DATA_DIR);

  // Wait for it to be ready (though constructor is sync, we might want to run some queries)
  // In pglite, it's usually ready immediately.

  await setupSchema();
}

async function setupSchema() {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position DOUBLE PRECISION NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT REFERENCES columns(id) ON DELETE CASCADE,
      text TEXT NOT NULL,
      position DOUBLE PRECISION NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `);

  // Seed data if columns are empty
  const { rows: columns } = await db.query('SELECT COUNT(*) as count FROM columns');
  if (parseInt(columns[0].count) === 0) {
    await db.query(`
      INSERT INTO columns (id, title, position) VALUES
      ('col-1', 'To Do', 10),
      ('col-2', 'In Progress', 20),
      ('col-3', 'Done', 30);
    `);
    console.log('Seeded default columns');
  }
}

const PORT = 3001;

async function startServer() {
  await initDb();
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });
}

startServer().catch(err => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

// Exporting db for other modules, but we'll keep it simple for now and use it within this file or import it.
// Since we are using ES modules, we might need a way to export the db.
export { db };

