app.patch('/api/cards/:id/move', async (req, res) => {
  const { id } = req.params;
  const { columnId, beforeId, afterId } = req.body;

  try {
    // We should do this in a transaction
    // In PGLite, we can use db.transaction() if it supports it, 
    // or just use BEGIN / COMMIT.
    // PGLite supports BEGIN/COMMIT.

    await db.query('BEGIN');

    // 1. Get current card info to make sure it exists and get its current column
    const { rows: currentCardRows } = await db.query('SELECT column_id FROM cards WHERE id = $1', [id]);
    if (currentCardRows.length === 0) {
      await db.query('ROLLBACK');
      return res.status(404).send('Card not found');
    }

    // 2. Calculate new position
    let newPosition = 50; // default

    if (beforeId && afterId) {
      // Between two cards
      const { rows: beforeCard } = await db.query('SELECT position FROM cards WHERE id = $1', [beforeId]);
      const { rows: afterCard } = await db.query('SELECT position FROM cards WHERE id = $2', [afterId]);

      if (beforeCard.length > 0 && afterCard.length > 0) {
        newPosition = (beforeCard[0].position + afterCard[0].position) / 2;
      } else if (beforeCard.length > 0) {
        newPosition = beforeCard[0].position - 5;
      } else if (afterCard.length > 0) {
        newPosition = afterCard[0].position + 5;
      }
    } else if (beforeId) {
      // Before a specific card
      const { rows: beforeCard } = await db.query('SELECT position FROM cards WHERE id = $1', [beforeId]);
      if (beforeCard.length > 0) {
        newPosition = beforeCard[0].position - 5;
      }
    } else if (afterId) {
      // After a specific card
      const { rows: afterCard } = await db.query('SELECT position FROM cards WHERE id = $1', [afterId]);
      if (afterCard.length > 0) {
        newPosition = afterCard[0].position + 5;
      }
    } else {
      // Just move to column, end of list
      const { rows: lastCard } = await db.query(
        'SELECT position FROM cards WHERE column_id = $1 ORDER BY position DESC LIMIT 1',
        [columnId]
      );
      if (lastCard.length > 0) {
        newPosition = lastCard[0].position + 10;
      }
    }

    // 3. Update the card
    const { rows: updatedCardRows } = await db.query(
      'UPDATE cards SET column_id = $1, position = $2 WHERE id = $3 RETURNING *',
      [columnId, newPosition, id]
    );

    if (updatedCardRows.length === 0) {
      await db.query('ROLLBACK');
      return res.status(404).send('Card not found during update');
    }

    const updatedCard = updatedCardRows[0];

    // 4. Check for collisions or precision issues and renormalize if needed
    // This is part of the requirement 3.5
    // To simplify, let's check if any other card has the same position in the same column
    const { rows: collisionCheck } = await db.query(
      'SELECT id FROM cards WHERE column_id = $1 AND position = $2 AND id != $3',
      [columnId, newPosition, id]
    );

    if (collisionCheck.length > 0) {
      // Renormalize the column
      const { rows: allCardsInCol } = await db.query(
        'SELECT id, position FROM cards WHERE column_id = $1 ORDER BY position ASC',
        [columnId]
      );

      // Reassign positions with steps of 10
      for (let i = 0; i < allCardsInCol.length; i++) {
        await db.query(
          'UPDATE cards SET position = $1 WHERE id = $2',
          [i * 10, allCardsInCol[i].id]
        );
      }

      // Get the updated card after renormalization
      const { rows: reupdatedCardRows } = await db.query(
        'SELECT * FROM cards WHERE id = $1',
        [id]
      );
      // We need to find which one it is. It's better to just redo the whole thing if collision.
      // But let's assume we want to broadcast the state of this card.
      // Actually, if we renormalize, we should broadcast the whole column or all changes.
      // Requirement 3.5 says: "detect collisions... and broadcast the corrected order".
      // To keep it simple for now, let's just use a more robust way to calculate position 
      // or renormalize and broadcast the whole board state? 
      // The requirement says "broadcast the corrected order".
