{"content": "const API_BASE = 'http://localhost:3001/api';

let boardState = [];

const boardElement = document.getElementById('board');

async function fetchBoard() {
  const response = await fetch(`${API_BASE}/board`);
  boardState = await response.json();
  renderBoard();
}

function renderBoard() {
  boardElement.innerHTML = '';
  boardState.forEach(column => {
    const columnEl = document.createElement('div');
    columnEl.className = 'column';
    columnEl.dataset.id = column.id;
    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="card-list" data-column-id="${column.id}"></div>
      <div class="card-form">
        <input type="text" placeholder="New card..." class="card-input">
        <button class="add-card-btn">Add</button>
      </div>
    `;

    const cardListEl = columnEl.querySelector('.card-list');
    column.cards.forEach(card => {
      const cardEl = createCardElement(card);
      cardListEl.appendChild(cardEl);
    });

    // Add card event
    columnEl.querySelector('.add-card-btn').addEventListener('click', () => {
      const input = columnEl.querySelector('.card-input');
      const text = input.value.trim();
      if (text) {
        createCard(column.id, text);
        input.value = '';
      }
    });

    // Drag and drop events on the card list
    cardListEl.addEventListener('dragover', handleDragOver);
    cardListEl.addEventListener('drop', handleDrop);

    boardElement.appendChild(columnEl);
  });
}

function createCardElement(card) {
  const cardEl = document.createElement('div');
  cardEl.className = 'card';
  cardEl.draggable = true;
  cardEl.id = `card-${card.id}`;
  cardEl.textContent = card.text;
  cardEl.dataset.id = card.id;

  cardEl.addEventListener('dragstart', handleDragStart);
  cardEl.addEventListener('dragend', handleDragEnd);

  return cardEl;
}

let draggedCardId = null;

function handleDragStart(e) {
  draggedCardId = e.target.dataset.id;
  e.target.classList.add('dragging');
}

function handleDragEnd(e) {
  e.target.classList.remove('dragging');
  draggedCardId = null;
}

function handleDragOver(e) {
  e.preventDefault();
  const cardList = e.currentTarget;
  const afterElement = getDragAfterElement(cardList, e.clientY);
  const draggingCard = document.getElementById(`card-${draggedCardId}`);
  if (afterElement == null) {
    cardList.appendChild(draggingCard);
  } else {
    cardList.insertBefore(draggingCard, afterElement);
  }
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll('.card:not(.dragging)')];

  return draggableElements.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      return { offset: offset, element: child };
    } else {
      return closest;
    }
  }, { offset: Number.NEGATIVE_INFINITY }).element;
}

async function createCard(columnId, text) {
  await fetch(`${API_BASE}/cards`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId, text })
  });
}

async function handleDrop(e) {
  e.preventDefault();
  const cardList = e.currentTarget;
  const columnId = cardList.dataset.columnId;
  const cardEl = document.getElementById(`card-${draggedCardId}`);

  // Find where it was dropped
  const afterElement = getDragAfterElement(cardList, e.clientY);

  // Find the card currently at that position
  let beforeId = null;
  let afterId = null;

  const cardsInCol = [...cardList.querySelectorAll('.card')];
  const index = cardsInCol.indexOf(cardEl);

  if (index > 0) {
    beforeId = cardsInCol[index - 1].dataset.id;
  }
  if (index < cardsInCol.length - 1) {
    afterId = cardsInCol[index + 1].dataset.id;
  }

  // If it was moved to a different column, we need to find the target column
  const targetColumnEl = cardEl.closest('.column');
  const targetColumnId = targetColumnEl.dataset.id;

  // If we moved to a different column, the before/after IDs from the original list might be wrong.
  // But wait, the `afterElement` is from the `cardList` where the drop happened.

  // Let's rethink the drop logic.
  // When drop happens, the DOM is already updated by handleDragOver.
  // We should use the DOM to determine the new order.

  // Let's get the new column and the new position in that column.

  // Actually, it's easier to just look at the DOM.
  // After drop, the card is in its new position in the DOM.
  // We can find its neighbors in the DOM.

  // But wait, we need to know the column it's in.
  const newColumnId = targetColumnId;

  // Re-calculate beforeId and afterId in the NEW column
  const newCardsInCol = [...cardList.querySelectorAll('.card')]; // Wait, this is only for the column we dropped into.
  // We need to find the card in the new column.

  // Let's find the card in the DOM of the target column.
  // Wait, `cardList` IS the target column's card list.

  const newCardsInColElement = cardList.querySelectorAll('.card');
  const newIndex = Array.from(newCardsInColElement).indexOf(cardEl);

  if (newIndex > 0) {
    beforeId = newCardsInColElement[newIndex - 1].dataset.id;
  } else {
    beforeId = null;
  }

  if (newIndex < newCardsInColElement.length - 1) {
    afterId = newCardsInColElement[newIndex + 1].dataset.id;
  } else {
    afterId = null;
  }

  // Send the move request
  await fetch(`${API_BASE}/cards/${draggedCardId}/move`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId: newColumnId, beforeId, afterId })
  });
}

function setupSSE() {
  const eventSource = new EventSource(`${window.location.origin.replace(':', '://') || 'http://localhost:3001'}/api/stream`); // This might not work if frontend is on different port.
  // Actually, the frontend is on Vite's port, backend is on 3001.
  // The SSE endpoint is on the backend.
  // So we should use http://localhost:3001/api/stream
  const sseUrl = 'http://localhost:3001/api/stream';
  const es = new EventSource(sseUrl);

  es.onmessage = (event) => {
    const { type, payload } = JSON.parse(event.data);
    console.log('SSE received:', type, payload);

    if (type === 'CARD_CREATED') {
      handleCardCreated(payload);
    } else if (type === 'CARD_MOVED') {
      handleCardMoved(payload);
    } else if (type === 'COLUMN_UPDATED') {
      handleColumnUpdated(payload);
    }
  };

  es.onerror = (err) => {
    console.error('SSE error:', err);
  };
}

function handleCardCreated(newCard) {
  // Find the column in state
  const column = boardState.find(c => c.id === newCard.columnId);
  if (column) {
    column.cards.push(newCard);
    // Re-render only the affected column to avoid losing drag state if possible
    // For simplicity, let's just re-render the whole board.
    renderBoard();
  }
}

function handleCardMoved(movedCard) {
  // 1. Remove from old position in state
  boardState.forEach(col => {
    col.cards = col.cards.filter(card => card.id !== movedCard.id);
  });

  // 2. Add to new position in state
  const column = boardState.find(c => c.id === movedCard.columnId);
  if (column) {
    column.cards.push(movedCard);
    column.cards.sort((a, b) => a.position - b.position);
  }

  renderBoard();
}

function handleColumnUpdated(payload) {
  const { columnId, cards } = payload;
  const column = boardState.find(c => c.id === columnId);
  if (column) {
    column.cards = cards;
    renderBoard();
  }
}

// Initialize
fetchBoard();
setupSSE();
