      const { rows: card } = await db.query('SELECT * FROM cards WHERE id = $1', [id]);
      return res.json(card[0]);
    }

    await db.query('COMMIT');

    const { rows: updatedCardRows } = await db.query(
      'SELECT * FROM cards WHERE id = $1',
      [id]
    );
