    broadcast('CARD_MOVED', updatedCard);
    res.json(updatedCard);

  } catch (err) {
    await db.query('ROLLBACK');
    console.error(err);
    res.status(500).send('Internal Server Error');
  }
});

const PORT = 3001;

async function startServer() {
  await initDb();
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });
