      // If collision, we re-index the column.

      // Wait, if I re-index, I need to notify clients about ALL moved cards.
      // Let's refine the "Move card" logic.
    }

    await db.query('COMMIT');

    // We need to broadcast the update.
    // Since the card might have changed position during renormalization, 
    // let's re-fetch it.
    // Actually, if I do renormalization, it's better to broadcast the whole column.
    // But the requirement says "broadcast every create and move with the canonical card and its column id".

    // Let's re-implement the move and renormalization more carefully.

    res.json(updatedCard);
    broadcast('CARD_MOVED', updatedCard);

  } catch (err) {
    await db.query('ROLLBACK');
    console.error(err);
    res.status(500).send('Internal Server Error');
